def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, 63)
        return min(budget, 28)

    yesterday_bids = []
    desperate_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_opponents += 1
        if opp.get('budget', 0) >= budget:
            rich_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev.get('bid', 0))

    player_count = 1 + len(alive_opponents)
    scarcity = float(supply) / float(player_count * WATER_REQ)

    if scarcity >= 1.2:
        base_bid = 20
    elif scarcity >= 0.95:
        base_bid = 30
    elif scarcity >= 0.75:
        base_bid = 40
    else:
        base_bid = 50

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
        pressure_bid = max(avg_prev + 2, highest_prev + 1)
        if highest_prev >= 60:
            if hp > 3 and no_water_days == 0:
                bid = min(base_bid, 24)
            else:
                bid = max(base_bid, 62)
        else:
            bid = max(base_bid, pressure_bid)
    else:
        bid = base_bid

    if desperate_opponents > 0:
        bid += 4
    if rich_opponents >= len(alive_opponents) and len(alive_opponents) > 0:
        bid -= 3

    if hp <= 2:
        bid = max(bid, 63)
    elif hp <= 4 or no_water_days >= 2:
        bid = max(bid, 54)
    elif no_water_days == 1:
        bid = max(bid, 44)

    reserve_floor = 0
    if hp > 4:
        reserve_floor = DAILY_SALARY * 2
    elif hp > 2:
        reserve_floor = DAILY_SALARY

    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = budget - reserve_floor + min(DAILY_SALARY, reserve_floor)

    if max_affordable < 0:
        max_affordable = 0

    final_bid = min(float(bid), float(max_affordable), float(budget))
    if final_bid < 0:
        final_bid = 0
    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    # Basic safety: if we are in danger, prioritize water.
    if my_status.get('hp', 0) <= 2:
        return min(my_status.get('budget', 0), DAILY_SALARY * 0.95)

    alive_opps = []
    for opp_id, st in opponents_status.items():
        if st.get('alive', False):
            alive_opps.append((opp_id, st))

    if not alive_opps:
        return min(my_status.get('budget', 0), DAILY_SALARY * 0.55)

    # Read yesterday behavior (single-step reaction only)
    prev_bids = []
    prev_pressures = []  # (opp_id, prev_bid, hp_after, budget_after)
    for opp_id, st in alive_opps:
        prev = st.get('previous_trace', {}) or {}
        pb = prev.get('bid', None)
        if pb is not None:
            prev_bids.append(pb)
            prev_pressures.append((opp_id, pb, prev.get('hp_after', None), prev.get('budget_after', None)))

    if not prev_bids:
        # Default: bid moderately to keep pace.
        return min(my_status.get('budget', 0), DAILY_SALARY * 0.55)

    highest_prev_bid = max(prev_bids)
    lowest_prev_bid = min(prev_bids)

    # If someone was willing to spend heavily yesterday, they likely value survival.
    # We shade our bid down unless our hp is also low.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status.get('hp', 0) > 3:
            bid = DAILY_SALARY * 0.65
        else:
            bid = DAILY_SALARY * 0.9
        return min(my_status.get('budget', 0), bid)

    # If everyone bid low yesterday, we can take advantage by bidding enough to win.
    if lowest_prev_bid <= DAILY_SALARY * 0.35:
        # Scale with how much water we need relative to expected supply.
        # supply is float; convert to int only for indexing-like operations (none here), but keep safe.
        expected_supply = float(supply)
        scarcity_factor = 1.0
        if expected_supply <= float(WATER_REQ):
            scarcity_factor = 1.25
        elif expected_supply <= 0.9 * float(WATER_REQ) + 15:  # medium heuristic
            scarcity_factor = 1.1
        bid = DAILY_SALARY * 0.6 * scarcity_factor
        # Also react to the gap vs highest bid.
        bid = max(bid, min(my_status.get('budget', 0), highest_prev_bid + 2.0))
        return min(my_status.get('budget', 0), bid)

    # Otherwise: mirror slightly above the median to stay competitive without overpaying.
    prev_bids_sorted = sorted(prev_bids)
    mid_index = int(len(prev_bids_sorted) // 2)
    median_prev_bid = prev_bids_sorted[mid_index]

    # If we have no-water days, we should increase urgency.
    no_water_days = my_status.get('no_water_days', 0)
    urgency = 1.0
    if no_water_days >= 2:
        urgency = 1.25
    elif no_water_days == 1:
        urgency = 1.1

    bid = median_prev_bid + 3.0
    bid = bid * urgency

    # Cap bid to avoid bankrupting.
    max_bid = min(my_status.get('budget', 0), DAILY_SALARY * 0.75)
    bid = min(bid, max_bid)

    # Ensure we bid at least a floor if we can.
    min_bid = min(my_status.get('budget', 0), DAILY_SALARY * 0.45)
    if bid < min_bid:
        bid = min_bid

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Day 1: No previous trace
    if day_context['day'] == 1:
        if my_status['hp'] <= 2:
            bid = min(my_status['budget'], DAILY_SALARY * 0.85)
        elif my_status['hp'] <= 4:
            bid = min(my_status['budget'], DAILY_SALARY * 0.6)
        else:
            bid = min(my_status['budget'], DAILY_SALARY * 0.4)
        return max(0, bid)

    # Gather yesterday's opponent bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid according to own need and supply
    supply = day_context['supply']
    # Low supply -> higher competition
    if supply < 20:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.45

    # Adjust for HP
    if my_status['hp'] <= 2:
        base = max(base, DAILY_SALARY * 0.9)
    elif my_status['hp'] <= 4:
        base = max(base, DAILY_SALARY * 0.6)

    # If yesterday opponents were aggressive, respond
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If someone was very desperate yesterday, they might be again
        if highest_prev > DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                # We can be safe and lower
                bid = min(my_status['budget'], base * 0.8)
            else:
                # We need to compete
                target = max(base, highest_prev * 0.95)
                bid = min(my_status['budget'], target)
        else:
            # Normal: set bid slightly above the highest if we need water
            if my_status['hp'] <= 3:
                bid = min(my_status['budget'], max(base, highest_prev + 2.0))
            else:
                bid = min(my_status['budget'], base)
    else:
        bid = min(my_status['budget'], base)

    # Ensure we do not bid more than we have
    return max(0, bid)
